  ('rep-16698', 'c-bot', null, 'k-eva', 'customer_summary', null, '2026-12', '2026-12-01', '2026-12-31', 'delivered', 1, '2027-01-14T16:00', 'u-johan', '2027-01-12T10:00', '2027-01-12T10:05', array['k-eva']::text[], '2027-01-13T08:30', null, false, null, null, null, false, null, null, null, false, null, null, null, null, null, null, null, null),
  ('rep-16699', 'c-bot', null, 'k-eva', 'customer_summary', null, '2027-01', '2027-01-01', '2027-01-31', 'draft', 1, '2027-02-10T16:00', null, null, null, '{}'::text[], null, null, false, null, 'I januari var 71 deltagare aktiva och 43 nya ärenden startade. 29 insatser avslutades, varav 10 till arbete eller studier. Närvarograden var 89 procent. En avvikelse har hanterats med åtgärdsplan.', null, false, null, null, null, false, null, null, null, null, null, null, null, null);
insert into public.messages (id, case_id, sender_id, body, created_at, read_by, read_at, kind) values
  ('msg-1', 'case-260143', 'k-maria', 'Hej! Hur går praktiken? Behöver hon stöd med resorna till Hallunda?', '2027-01-27T09:14', array['u-amira']::text[], '2027-01-27T10:02', null),
  ('msg-2', 'case-260143', 'u-amira', 'Hej Maria! Det går bra. Hon tar bussen själv sedan i måndags. Jag återkommer efter uppföljningen med handledaren på torsdag.', '2027-01-27T10:10', array['k-maria']::text[], '2027-01-27T13:40', null),
  ('msg-3', 'case-260143', 'k-maria', 'Tack! Kan vi ses på ett uppföljningsmöte vecka 6? Jag kan tisdag eller torsdag förmiddag.', '2027-02-01T08:15', '{}'::text[], null, null),
  ('msg-4', 'case-260148', 'u-amira', 'Hej Maria. Deltagaren har varit borta utan att meddela två gånger inom 14 dagar. Jag föreslår ett uppföljningsmöte för att gå igenom planen. Förslag på tider: onsdag 3/2 kl. 10 eller torsdag 4/2 kl. 14.', '2027-01-28T11:30', array['k-maria']::text[], '2027-01-28T12:05', null),
  ('msg-5', 'case-260148', 'k-maria', 'Onsdag kl. 10 passar. Jag kommer till Alby.', '2027-01-29T08:50', array['u-amira']::text[], '2027-01-29T09:30', null),
  ('msg-6', 'case-260117', 'u-johan', 'Hej Ahmed. Decemberfakturan returnerades eftersom beställarreferensen 55102983 inte finns hos er. Kan du bekräfta rätt referens?', '2027-01-13T10:00', array['k-ahmed']::text[], '2027-01-13T11:00', null),
  ('msg-7', 'case-260117', 'k-ahmed', 'Förlåt, siffrorna blev omkastade. Rätt referens är 55102938. Den gäller båda mina ärenden från november.', '2027-01-14T08:40', array['u-johan']::text[], '2027-01-14T09:00', null);
