insert into public.participant_voice_notes (id, case_id, link_id, language, text_sv, text_original, consent_text_version, consent_given_at, status, created_at, reviewed_by, reviewed_at, ai_run_id) values
  ('pvn-yusuf', 'case-260148', 'vl-yusuf', 'sv', 'Hej. Jag har haft svårt att komma i tid på morgonen eftersom bussen går sällan. Jag vill fortsätta, jag tycker om arbetet. Kan vi prata om att börja en halvtimme senare?', null, 'röst-v1.0 (2026-09-30)', '2027-01-26T07:53', 'reviewed', '2027-01-26T07:55', 'u-amira', '2027-01-26T10:20', null),
  ('pvn-nadia', 'case-260143', 'vl-nadia', 'so', 'Hej, det är jag. Praktiken har börjat bra och jag trivs med arbetsuppgifterna. Det hjälper mig när instruktionerna är skrivna, för då kan jag läsa dem igen. Jag vill gärna prata om vad som händer efter praktiken.', 'Haye, waa aniga. Tababarka shaqadu si fiican ayuu u bilaabmay, waxaana ku faraxsanahay hawlaha. Waxaa i caawiya marka tilmaamaha la qoro, sababtoo ah markaas mar kale ayaan akhrin karaa. Waxaan jeclaan lahaa inaan ka wada hadalno waxa dhacaya tababarka kadib.', 'röst-v1.0 (2026-09-30)', '2027-01-28T19:40', 'new', '2027-01-28T19:42', null, null, null);
